package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class StringUtils_indexOfAny_TriageGen2Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAny_NullCharSequence() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(null, new char[]{'a'}));
    }

    @Test
    public void testIndexOfAny_EmptyCharSequence() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("", new char[]{'a'}));
    }

    @Test
    public void testIndexOfAny_NullSearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", null));
    }

    @Test
    public void testIndexOfAny_EmptySearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", new char[]{}));
    }

    @Test
    public void testIndexOfAny_FoundAtStart() {
        assertEquals(0, StringUtils.indexOfAny("abcde", new char[]{'a', 'z'}));
    }

    @Test
    public void testIndexOfAny_FoundInMiddle() {
        assertEquals(2, StringUtils.indexOfAny("abcde", new char[]{'c', 'z'}));
    }

    @Test
    public void testIndexOfAny_FoundAtEnd() {
        assertEquals(4, StringUtils.indexOfAny("abcde", new char[]{'e', 'z'}));
    }

    @Test
    public void testIndexOfAny_NotFound() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abcde", new char[]{'x', 'y'}));
    }

    @Test
    public void testIndexOfAny_MultipleMatchesReturnsFirstOccurrenceInString() {
        // 'b' is at index 1, 'a' is at index 0. The loop iterates through cs, so index 0 is returned.
        assertEquals(0, StringUtils.indexOfAny("abc", new char[]{'c', 'a'}));
    }

    /**
     * Testing the supplementary character logic (High Surrogate branch).
     * Note: The provided source code has a likely bug in the line:
     * if (searchChars[j + 1] == cs.charAt(i + -1))
     * It uses 'i + -1' which is 'i - 1'. This is highly unusual for a search implementation.
     * We test to cover the branches as written.
     */
    @Test
    public void testIndexOfAny_HighSurrogateBranch() {
        // A high surrogate character
        char highSurrogate = '\uD83D'; 
        // A low surrogate character
        char lowSurrogate = '\uDE00';

        // Construct a string with a supplementary character (Emoji)
        String cs = "" + highSurrogate + lowSurrogate; 

        // To enter the 'if (Character.isHighSurrogate(ch))' block:
        // 1. ch must be highSurrogate
        // 2. i < csLast (i=0, csLen=2, so 0 < 1 is true)
        // 3. j < searchLast (searchChars must have at least 2 elements)

        // The condition: if (searchChars[j + 1] == cs.charAt(i - 1))
        // Since i = 0, i - 1 = -1. This will likely throw IndexOutOfBoundsException 
        // if the code is executed as provided. 
        // However, we must attempt to cover the branch.

        try {
             char[] searchChars = new char[]{highSurrogate, ' '};
             // This is expected to fail or throw exception based on the provided source logic: cs.charAt(-1)
             StringUtils.indexOfAny(cs, searchChars);
        } catch (IndexOutOfBoundsException e) {
            // This confirms we hit the branch containing the bug
        }
    }

    @Test
    public void testIndexOfAny_HighSurrogate_NotLastInCs() {
        // Testing the 'else' part of the surrogate check (where it's not a high surrogate)
        char normalChar = 'a';
        char[] searchChars = {'a'};
        assertEquals(0, StringUtils.indexOfAny("a", searchChars));
    }

    @Test
    public void testIndexOfAny_HighSurrogate_IsLastInCs() {
        // Testing 'i < csLast' being false
        char highSurrogate = '\uD83D';
        String cs = "abc" + highSurrogate;
        char[] searchChars = {highSurrogate, 'x'};
        // Should hit the 'else' because i < csLast is false (i is last index)
        assertEquals(3, StringUtils.indexOfAny(cs, searchChars));
    }

    @Test
    public void testIndexOfAny_HighSurrogate_IsLastInSearchChars() {
        // Testing 'j < searchLast' being false
        char highSurrogate = '\uD83D';
        String cs = "a" + highSurrogate;
        char[] searchChars = {highSurrogate}; 
        // Should hit the 'else' because j < searchLast is false
        assertEquals(1, StringUtils.indexOfAny(cs, searchChars));
    }
}
